pub fn acosf<'a>(ctx: &'a Ctx, x: f64) -> f64 {
    let __frame = ctx.stack_frame(0x8);
    let mut x = x;
    let mut result: f64 = fp::fnmsubs(x, x, 1.0);
    if result > fp::frsp(0_i32 as f64) {
        let mut guess: f64 = 0.0;
        guess = fp::frsp(fp::frsqrte(result));
        guess = fp::fmuls(
            fp::fmuls(0.5, guess),
            (fp::fnmsubs(result, fp::fmuls(guess, guess), 3.0)),
        );
        guess = fp::fmuls(
            fp::fmuls(0.5, guess),
            (fp::fnmsubs(result, fp::fmuls(guess, guess), 3.0)),
        );
        guess = fp::fmuls(
            fp::fmuls(0.5, guess),
            (fp::fnmsubs(result, fp::fmuls(guess, guess), 3.0)),
        );
        result = guess;
    } else if (result != 0.0) {
        result = ptr::<ArrV<'a, F32, 0>>(ctx, 0x80400770).at(0_i32).get();
    } else {
        result = ptr::<ArrV<'a, F32, 0>>(ctx, 0x80400774).at(0_i32).get();
    }
    return fp::fsubs(
        fp::frsp((fp::fdiv(3.141592653589793, (2_i32 as f64)))),
        fns::atanf(ctx, fp::fmuls(x, result)),
    );
}

pub fn asinf<'a>(ctx: &'a Ctx, x: f64) -> f64 {
    let __frame = ctx.stack_frame(0x18);
    let mut x = x;
    return fns::atanf(
        ctx,
        fp::fmuls(
            x,
            statics::melee__lb__lbtrigf::lb_sqrtf(ctx, fp::fnmsubs(x, x, 1.0)),
        ),
    );
}

pub fn lb_sqrtf<'a>(ctx: &'a Ctx, x: f64) -> f64 {
    let mut x = x;
    if x > 0.0 {
        let mut guess: f64 = 0.0;
        guess = fp::frsp(fp::frsqrte(x));
        guess = fp::fmuls(
            fp::fmuls(0.5, guess),
            (fp::fnmsubs(x, fp::fmuls(guess, guess), 3.0)),
        );
        guess = fp::fmuls(
            fp::fmuls(0.5, guess),
            (fp::fnmsubs(x, fp::fmuls(guess, guess), 3.0)),
        );
        guess = fp::fmuls(
            fp::fmuls(0.5, guess),
            (fp::fnmsubs(x, fp::fmuls(guess, guess), 3.0)),
        );
        return guess;
    }
    if (x != 0.0) {
        return ptr::<ArrV<'a, F32, 0>>(ctx, 0x80400770).at(0_i32).get();
    }
    return ptr::<ArrV<'a, F32, 0>>(ctx, 0x80400774).at(0_i32).get();
}

